const out = [];
for (const it of $input.all()) for (const model of ['claude-haiku-5-5', 'claude-sonnet-5-5']) out.push({ json: { ...it.json, model } });
return out;

// Lots par journee, recus en JSON { lots: [...] }.
const b = $input.first().json.body || {};
const L = Array.isArray(b) ? b : (b.lots || []);
if (!L.length) throw new Error('Aucun lot recu');
return L.map(l => ({ json: { jour: l.jour, texte: l.texte } }));

// Planning du jour de chaque lot (meme mise en forme que le workflow de production).
const lots = $('Lots').all();
const res = $input.all();
return lots.map((l, i) => {
  const r = (res[i] || {}).json || {};
  const items = (r.ok && r.data && Array.isArray(r.data.items)) ? r.data.items : [];
  const lignes = items.map(ev => {
    const c = ev.client || {};
    const a = ev.address || c.address || {};
    const techs = (ev.users || []).map(u => u.firstName || u.name || u.id).join(', ');
    return '- ' + (ev.heureParis || '') + ' ' + String(c.name || ev.clientName || '?').trim() + ' (client_id ' + (c.id || ev.clientId || '?') + ') ' + (a.city || '') + ' ; ' + String(ev.title || ev.name || ev.type || '').replace(/<[^>]+>/g, ' ').slice(0, 120) + ' ; techniciens : ' + techs;
  });
  return { json: { jour: l.json.jour, texte: l.json.texte, planning: lignes.join('\n').slice(0, 6000) || '(aucune intervention trouvee ce jour-la)' } };
});

// Une ligne par lot et par modele : notes retenues + tokens.
const src = $('Croiser').all();
return $input.all().map((it, i) => {
  const s = (src[i] || {}).json || {};
  const r = it.json || {};
  let t = ''; try { t = (r.content || []).map(c => c.text || '').join('').trim(); } catch (e) {}
  let notes = null; try { const a = t.indexOf('{'), b = t.lastIndexOf('}'); notes = JSON.parse(t.slice(a, b + 1)).notes; } catch (e) {}
  return { json: { jour: s.jour, model: s.model, ok: Array.isArray(notes), notes: notes || [], brut: Array.isArray(notes) ? '' : (t || JSON.stringify(r.error || r).slice(0, 300)), out_tokens: (r.usage || {}).output_tokens || 0, in_tokens: (r.usage || {}).input_tokens || 0 } };
});
